CREATE TABLE npc_dialogue_npc(id TEXT PRIMARY KEY,ordinal INTEGER NOT NULL UNIQUE,native_id TEXT NOT NULL) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_npc_insert BEFORE INSERT ON npc_dialogue_npc WHEN EXISTS(SELECT 1 FROM npc_dialogue_npc WHERE id=NEW.id OR ordinal=NEW.ordinal) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_npc_update BEFORE UPDATE ON npc_dialogue_npc BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_npc_delete BEFORE DELETE ON npc_dialogue_npc BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TABLE npc_dialogue_source(path TEXT PRIMARY KEY,size INTEGER NOT NULL,sha256 TEXT NOT NULL,blob TEXT NOT NULL) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_source_insert BEFORE INSERT ON npc_dialogue_source WHEN EXISTS(SELECT 1 FROM npc_dialogue_source WHERE path=NEW.path) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_source_update BEFORE UPDATE ON npc_dialogue_source BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_source_delete BEFORE DELETE ON npc_dialogue_source BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TABLE npc_dialogue_container(id TEXT PRIMARY KEY,source_path TEXT NOT NULL REFERENCES npc_dialogue_source(path),pointer TEXT NOT NULL,runtime_run TEXT,runtime_id TEXT,UNIQUE(source_path,pointer)) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_container_insert BEFORE INSERT ON npc_dialogue_container WHEN EXISTS(SELECT 1 FROM npc_dialogue_container WHERE id=NEW.id OR (source_path=NEW.source_path AND pointer=NEW.pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_container_update BEFORE UPDATE ON npc_dialogue_container BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_container_delete BEFORE DELETE ON npc_dialogue_container BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TABLE npc_dialogue_relation(id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES npc_dialogue_container(id),pointer TEXT NOT NULL,kind TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL,UNIQUE(container_id,pointer,kind)) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_relation_insert BEFORE INSERT ON npc_dialogue_relation WHEN EXISTS(SELECT 1 FROM npc_dialogue_relation WHERE id=NEW.id OR (container_id=NEW.container_id AND pointer=NEW.pointer AND kind=NEW.kind)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_relation_update BEFORE UPDATE ON npc_dialogue_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_relation_delete BEFORE DELETE ON npc_dialogue_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TABLE npc_dialogue_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES npc_dialogue_relation(id),npc_id TEXT NOT NULL REFERENCES npc_dialogue_npc(id),UNIQUE(relation_id,npc_id)) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_candidate_insert BEFORE INSERT ON npc_dialogue_candidate WHEN EXISTS(SELECT 1 FROM npc_dialogue_candidate WHERE id=NEW.id OR (relation_id=NEW.relation_id AND npc_id=NEW.npc_id)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_candidate_update BEFORE UPDATE ON npc_dialogue_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_candidate_delete BEFORE DELETE ON npc_dialogue_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TABLE npc_dialogue_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE TRIGGER npc_dialogue_release_insert BEFORE INSERT ON npc_dialogue_release WHEN EXISTS(SELECT 1 FROM npc_dialogue_release WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_release_update BEFORE UPDATE ON npc_dialogue_release BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER npc_dialogue_release_delete BEFORE DELETE ON npc_dialogue_release BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE INDEX npc_dialogue_candidate_npc ON npc_dialogue_candidate(npc_id,relation_id);
CREATE INDEX npc_dialogue_npc_native ON npc_dialogue_npc(native_id);
